/**
 * Copy CLI Tool
 *
 * Copies databases from a source environment to a target environment.
 * Designed to refresh staging/demo environments with production data or copy from one staging to another.
 *
 * Usage: npx tsx bin/copy.ts --config copy.json
 *
 * The config file is generated by prep-copy.ts which extracts all necessary
 * connection details from GitHub environment secrets.
 *
 * Safety:
 * - Source CAN be production (typical use case: copy prod data to staging)
 * - Target CANNOT be production unless the operator explicitly confirmed it
 *   (prep-copy.ts --allow-production, set via the workflow's confirm_prod input)
 * - Both source and target must be online and have active deployments
 * - Smoke tests validate connectivity before any destructive operations
 */

import * as fs from 'fs';
import { parseCopyConfig } from '../config/copy-config';
import { CopyOrchestrator } from '../lib/orchestrators/copy';
import { logger, logReport } from '../lib/utils/logger';

function parseArgs(args: string[]): { configPath: string } {
  let configPath: string | undefined;

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    const nextArg = args[i + 1];

    switch (arg) {
      case '--config':
      case '-c':
        configPath = nextArg;
        i++;
        break;
      case '-h':
      case '--help':
        printUsage();
        process.exit(0);
        break;
      default:
        if (arg.startsWith('-')) {
          throw new Error(`Unknown argument: ${arg}`);
        }
    }
  }

  if (!configPath) {
    throw new Error('Missing required argument: --config <file>');
  }

  return { configPath };
}

function printUsage(): void {
  console.log(`
Usage: npx tsx bin/copy.ts --config <file>

Options:
  -c, --config <file>  Path to copy configuration JSON file (from prep-copy.ts)
  -h, --help           Show this help message

Example:
  npx tsx bin/copy.ts --config copy.json
`);
}

async function main(): Promise<void> {
  logger.info('📋 deploy3 Data Copy');
  logger.info('');

  // Parse CLI arguments
  const { configPath } = parseArgs(process.argv.slice(2));

  // Verify config file exists
  if (!fs.existsSync(configPath)) {
    logger.error(`❌ Config file not found: ${configPath}`);
    process.exit(1);
  }

  // Read and parse config
  const configJson = fs.readFileSync(configPath, 'utf-8');
  const copyConfig = parseCopyConfig(configJson);

  logger.info('Configuration:');
  logger.info(`  App Name: ${copyConfig.appName}`);
  logger.info(
    `  Source: ${copyConfig.source.ssh.host}:${copyConfig.source.ssh.port} (${copyConfig.source.domain})`
  );
  logger.info(
    `  Target: ${copyConfig.target.ssh.host}:${copyConfig.target.ssh.port} (${copyConfig.target.domain})`
  );
  logger.info(`  Databases: ${copyConfig.databases.length}`);
  logger.info('');

  // Create and run orchestrator
  const orchestrator = new CopyOrchestrator({ copyConfig }, { logger });

  logger.info('Starting copy...');
  logger.info('');

  const report = await orchestrator.run();

  // Print report
  logReport(logger, report, 'Copy');

  process.exit(report.success ? 0 : 1);
}

main().catch((error) => {
  logger.error('❌ Copy failed');
  logger.error(error instanceof Error ? error.message : String(error));
  if (error instanceof Error && error.stack) {
    logger.error(error.stack);
  }
  process.exit(1);
});
